<?php require_once __DIR__.'/seguridad.php';simceRequireRole(array('plataforma_superadmin'),false);?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administración de colegios</title><style>body{font-family:Arial;background:#f1f5f9;color:#172554;padding:24px}main{max-width:1050px;margin:auto}section{background:#fff;padding:24px;border-radius:16px;margin:18px 0}input,button{padding:11px;margin:4px;border:1px solid #94a3b8;border-radius:8px}button{background:#1d4ed8;color:#fff;border:0;font-weight:700}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.version{position:fixed;right:12px;bottom:10px;color:#64748b;font-weight:bold}</style></head><body><main><h1>Plataforma multi-colegio</h1><p>Superadministración general. Cada colegio mantiene usuarios y datos independientes.</p><section><h2>Crear colegio y administrador inicial</h2><input id="code" placeholder="Código: colegio-norte"><input id="schoolName" placeholder="Nombre del colegio"><input id="user" placeholder="Usuario administrador"><input id="pass" type="password" placeholder="Contraseña segura"><button id="create">Crear colegio</button><p id="msg"></p></section><section><h2>Colegios registrados</h2><div id="list"></div></section></main><div class="version">v2.1.0</div><script src="sesion-cliente.js"></script><script>
const msg=document.querySelector('#msg');async function call(body){const r=await window.simceAuthenticatedFetch('plataforma_api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return r.json()}async function load(){const x=await fetch('plataforma_api.php').then(r=>r.json());document.querySelector('#list').innerHTML='<table><tr><th>Código</th><th>Colegio</th><th>Usuarios</th><th>Alumnos</th><th>Estado</th></tr>'+x.colegios.map(c=>'<tr><td>'+c.codigo+'</td><td>'+c.nombre+'</td><td>'+c.usuarios+'</td><td>'+c.alumnos+'</td><td><button onclick="toggle('+c.id+','+(c.activo?0:1)+')">'+(c.activo?'Desactivar':'Activar')+'</button></td></tr>').join('')+'</table>'}document.querySelector('#create').onclick=async()=>{const x=await call({action:'create_school',codigo:code.value,nombre:schoolName.value,usuario:user.value,password:pass.value});msg.textContent=x.ok?'Colegio creado.':x.error;if(x.ok)load()};async function toggle(id,activo){await call({action:'toggle_school',id,activo});load()}load();
</script></body></html>
